class Node(object):

    def __init__(self, value=None, children=None):
        self.value = value
        self.children = children if children is not None else []

    def is_leaf(self):
        return len(self.children) == 0


def build(spec):
    """7 -> a leaf, [a, b] -> a node with children, (h, [a, b]) -> the
    same node carrying value h, a heuristic estimate of that position."""
    if isinstance(spec, tuple):
        return Node(spec[0], [build(child) for child in spec[1]])
    if isinstance(spec, list):
        return Node(None, [build(child) for child in spec])
    return Node(spec)


def height(node):
    if node.is_leaf():
        return 0
    max_height = 0

    for child in node.children:
        child_height = height(child)
        if child_height > max_height:
            max_height = child_height
    return 1 + max_height

def max_leaf(node):
    if node.is_leaf():
        return node.value

    max_val = -1000000
    for child in node.children:
        child_max = max_leaf(child)
        if child_max > max_val:
            max_val = child_max
    return max_val

